const itemsIn = $input.all();

let total = 0;
let count = itemsIn.length;
const categoryTotals = {};
let topExpense = null;

for (const item of itemsIn) {
  const row = item.json;
  const amount = Number(row.amount || 0);
  const category = row.final_category || row.ai_category || row.category || 'Other';
  const description = row.description || '';

  total += amount;

  if (!categoryTotals[category]) {
    categoryTotals[category] = 0;
  }
  categoryTotals[category] += amount;

  if (!topExpense || amount > topExpense.amount) {
    topExpense = {
      amount,
      description,
      category,
    };
  }
}

const sortedCategories = Object.entries(categoryTotals)
  .sort((a, b) => b[1] - a[1])
  .map(([category, amount]) => `${category}: ${amount} JOD`);

return [
  {
    json: {
      date: new Date().toISOString().slice(0, 10),
      total_expenses: total,
      transaction_count: count,
      top_categories: sortedCategories.join('\n'),
      top_expense_description: topExpense ? topExpense.description : 'N/A',
      top_expense_amount: topExpense ? topExpense.amount : 0,
      top_expense_category: topExpense ? topExpense.category : 'N/A',
    },
  },
];
